const xml = $input.first().json.data;
const itemBlocks = [];
let m;
const re = /<item>([\s\S]*?)<\/item>/g;
while ((m = re.exec(xml)) !== null && itemBlocks.length < 6) { itemBlocks.push(m[1]); }
function extractTag(block, tag) {
  const r = new RegExp('<' + tag + '[\\s\\S]*?>([\\s\\S]*?)<\\/' + tag + '>');
  const x = block.match(r);
  if (!x) return '';
  return x[1].replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '').replace(/<[^>]+>/g, '').replace(/&[a-z]+;/gi, ' ').trim();
}
const noticias = itemBlocks.map(function(b) {
  return { title: extractTag(b,'title'), link: extractTag(b,'link'), desc: extractTag(b,'description').substring(0,280) };
}).filter(function(n){ return n.title; });
const fecha = new Date().toLocaleDateString('en-US',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
const rows = noticias.map(function(n){
  return '<div style="border-left:4px solid #6366f1;padding:14px 18px;margin-bottom:20px;background:#fafafa"><a href="'+n.link+'" style="font-size:15px;font-weight:700;color:#1e1b4b;text-decoration:none">'+n.title+'</a><p style="color:#6b7280;font-size:13px;margin:8px 0">'+n.desc+'...</p><a href="'+n.link+'" style="font-size:12px;color:#6366f1">Read more</a></div>';
}).join('');
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto"><div style="background:linear-gradient(135deg,#4f46e5,#7c3aed);padding:32px;text-align:center"><h1 style="color:#fff;margin:0">AI News Update</h1><p style="color:#c7d2fe;margin:8px 0 0">'+fecha+'</p></div><div style="padding:24px">'+rows+'<p style="font-size:12px;color:#9ca3af;margin-top:20px">Source: TechCrunch AI | Sent daily | n8n</p></div></body></html>';
return [{ json: { html: html, subject: 'AI News Update - ' + fecha } }];
